// The testdata golden files were generated by the Python implementation this
// program replaces, so these tests pin byte-for-byte parity with what
// Tampermonkey was already accepting.

func TestTMHashMatchesReference(t *testing.T) {
	raw, err := os.ReadFile("testdata/hashes.json")
	if err != nil {
		t.Fatal(err)
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var cases map[string]struct {
		Value any    `json:"value"`
		Hash  string `json:"hash"`
	}
	if err := dec.Decode(&cases); err != nil {
		t.Fatal(err)
	}
	for name, c := range cases {
		if got := tmHash(c.Value); got != c.Hash {
			t.Errorf("%s: tmHash(%v) = %s, want %s", name, c.Value, got, c.Hash)
		}
	}
}

func TestPolicyEntryAndPlistMatchReference(t *testing.T) {
	t.Setenv("TM_FIXTURE_HOST", "box.example")
	doc, err := buildProvisioning([]string{"testdata/fixture.user.js"})
	if err != nil {
		t.Fatal(err)
	}
	entry, err := newPolicyEntry(doc)
	if err != nil {
		t.Fatal(err)
	}
	var want struct {
		Hash string `json:"hash"`
		URL  string `json:"url"`
	}
	raw, _ := os.ReadFile("testdata/fixture.entry.json")
	if err := json.Unmarshal(raw, &want); err != nil {
		t.Fatal(err)
	}
	if entry.Hash != want.Hash {
		t.Errorf("hash = %s, want %s", entry.Hash, want.Hash)
	}
	if entry.URL != want.URL {
		t.Errorf("data URL differs from the reference")
	}
	wantPlist, _ := os.ReadFile("testdata/fixture.plist")
	if got := policyPlist(entry); !bytes.Equal(got, wantPlist) {
		t.Errorf("plist differs from the reference:\n%s", got)
	}
}

func TestExpandEnvPlaceholdersOnlyUpperCase(t *testing.T) {
	t.Setenv("TM_HOST", "box")
	got, err := expandEnvPlaceholders("a ${TM_HOST} b ${host} c ${TM_PORT:-9988} d ${target.port}")
	if err != nil {
		t.Fatal(err)
	}
	if want := "a box b ${host} c 9988 d ${target.port}"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
	if _, err := expandEnvPlaceholders("${TM_SURELY_UNSET_VAR}"); err == nil {
		t.Error("an unset UPPER_CASE placeholder with no default: want an error, got nil")
	}
}

func TestBuildProvisioningNeedsAName(t *testing.T) {
	p := filepath.Join(t.TempDir(), "nameless.user.js")
	os.WriteFile(p, []byte("// ==UserScript==\n// @version 1\n// ==/UserScript==\n"), 0o644)
	if _, err := buildProvisioning([]string{p}); err == nil || !strings.Contains(err.Error(), "@name") {
		t.Errorf("want a missing-@name error, got %v", err)
	}
}

// writeLog builds a LevelDB log file holding the given batches, each written
// as one FULL record.
func writeLog(t *testing.T, dir string, batches ...[]byte) {
	t.Helper()
	var buf bytes.Buffer
	for _, b := range batches {
		hdr := make([]byte, logHeader)
		binary.LittleEndian.PutUint16(hdr[4:], uint16(len(b)))
		hdr[6] = recFull
		buf.Write(hdr)
		buf.Write(b)
	}
	if err := os.WriteFile(filepath.Join(dir, "000003.log"), buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
}

type op struct {
	key, value string
	del        bool
}

func batch(seq uint64, ops ...op) []byte {
	b := make([]byte, 12)
	binary.LittleEndian.PutUint64(b, seq)
	binary.LittleEndian.PutUint32(b[8:], uint32(len(ops)))
	for _, o := range ops {
		if o.del {
			b = append(b, 0)
		} else {
			b = append(b, 1)
		}
		b = binary.AppendUvarint(b, uint64(len(o.key)))
		b = append(b, o.key...)
		if !o.del {
			b = binary.AppendUvarint(b, uint64(len(o.value)))
			b = append(b, o.value...)
		}
	}
	return b
}

func TestLevelDBLogKeepsNewestAndDropsDeleted(t *testing.T) {
	dir := t.TempDir()
	writeLog(t, dir,
		batch(1, op{key: "a", value: "old"}, op{key: "gone", value: "x"}),
		batch(3, op{key: "a", value: "new"}, op{key: "gone", del: true}),
	)
	kv := leveldbLogKV(dir)
	if string(kv["a"].value) != "new" {
		t.Errorf("a = %q, want %q", kv["a"].value, "new")
	}
	if _, ok := kv["gone"]; ok {
		t.Error("a deleted key is still reported")
	}
}

func TestReadProfileState(t *testing.T) {
	userData := t.TempDir()
	managed := filepath.Join(userData, "Default", "Managed Extension Settings", tampermonkeyID)
	local := filepath.Join(userData, "Default", "Local Extension Settings", tampermonkeyID)
	os.MkdirAll(managed, 0o755)
	os.MkdirAll(local, 0o755)
	writeLog(t, managed, batch(1, op{key: "jsonImport", value: `[{"hash":"1:abc"}]`}))
	writeLog(t, local,
		batch(1,
			op{key: "@meta#uid-1", value: `{"value":{"name":"Log bridge","version":"1.0"}}`},
			op{key: "#managed#consumed", value: `{"value":{"1:abc":true}}`},
		),
		// Reinstalled under a new uid: the newer record is the current version.
		batch(5, op{key: "@meta#uid-2", value: `{"value":{"name":"Log bridge","version":"2.0"}}`}),
	)
	st := readProfileState(userData, "Default")
	if len(st.Delivered) != 1 || st.Delivered[0] != "1:abc" {
		t.Errorf("delivered = %v", st.Delivered)
	}
	if st.Installed["Log bridge"] != "2.0" {
		t.Errorf("installed = %v", st.Installed)
	}
	if len(st.Consumed) != 1 || st.Consumed[0] != "1:abc" {
		t.Errorf("consumed = %v", st.Consumed)
	}
}
